from __future__ import absolute_import

from taf.selenium.sbts.pages import v23r4
from .configuration_management import ParameterEditorPage
from .configuration_management import ConfigurationAutomationPage
from .centralized_rae_management import CentralizedRaeManagementPage
from .centralized_ret_management import CentralizedRetManagementPage


class Configuration(v23r4.Configuration):
    """
    The class corresponding to Configuration page on selenium_sbts web, all operations under Configuration
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker, screenshot_dir):
        super(Configuration, self).__init__(driver, download_checker, screenshot_dir)
        self._parameter_editor = ParameterEditorPage(driver, download_checker, screenshot_dir)
        self._configuration_automation = ConfigurationAutomationPage(driver)
        self._centralized_rae_management = CentralizedRaeManagementPage(driver, download_checker)
        self._centralized_ret_management = CentralizedRetManagementPage(driver)
